package com.twelvemonkeys.imageio.plugins.bmp;

import org.junit.jupiter.api.Test;

import javax.imageio.IIOException;
import javax.imageio.ImageReadParam;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class BMPImageReaderReadTests {
    @Test
    void readsBottomUp24BitBmpAndHonorsRowPadding() throws IOException {
        BMPImageReader reader = new BMPImageReader();
        reader.setInput(new MemoryCacheImageInputStream(new ByteArrayInputStream(createBmp24())));

        BufferedImage image = reader.read(0, null);

        assertEquals(3, image.getWidth());
        assertEquals(2, image.getHeight());

        assertEquals(0xFFFFFF00, image.getRGB(0, 0));
        assertEquals(0xFFFF00FF, image.getRGB(1, 0));
        assertEquals(0xFF00FFFF, image.getRGB(2, 0));

        assertEquals(0xFFFF0000, image.getRGB(0, 1));
        assertEquals(0xFF00FF00, image.getRGB(1, 1));
        assertEquals(0xFF0000FF, image.getRGB(2, 1));
    }

    @Test
    void rejectsImageIndexOutsideAvailableImages() throws IOException {
        BMPImageReader reader = new BMPImageReader();
        reader.setInput(new MemoryCacheImageInputStream(new ByteArrayInputStream(createBmp24())));

        assertThrows(IndexOutOfBoundsException.class, () -> reader.read(1, null));
    }

    @Test
    void rejectsUnsupportedCompression() throws IOException {
        BMPImageReader reader = new BMPImageReader();
        reader.setInput(new MemoryCacheImageInputStream(
                new ByteArrayInputStream(createBmp24WithCompression(99))));

        assertThrows(IIOException.class, () -> reader.read(0, new ImageReadParam()));
    }

    private static byte[] createBmp24() {
        return createBmp24WithCompression(0);
    }

    private static byte[] createBmp24WithCompression(int compression) {
        byte[] bmp = new byte[78];

        bmp[0] = 'B';
        bmp[1] = 'M';
        putInt(bmp, 2, bmp.length);
        putInt(bmp, 10, 54);

        putInt(bmp, 14, 40);
        putInt(bmp, 18, 3);
        putInt(bmp, 22, 2);
        putShort(bmp, 26, 1);
        putShort(bmp, 28, 24);
        putInt(bmp, 30, compression);
        putInt(bmp, 34, 24);
        putInt(bmp, 38, 2835);
        putInt(bmp, 42, 2835);

        int offset = 54;

        // Bottom row: red, green, blue, followed by one padding byte.
        bmp[offset++] = 0;
        bmp[offset++] = 0;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = 0;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = 0;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = 0;
        bmp[offset++] = 0;

        // Top row: yellow, magenta, cyan, followed by one padding byte.
        bmp[offset++] = 0;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = 0;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset++] = (byte) 0xFF;
        bmp[offset] = 0;

        return bmp;
    }

    private static void putShort(byte[] data, int offset, int value) {
        data[offset] = (byte) value;
        data[offset + 1] = (byte) (value >>> 8);
    }

    private static void putInt(byte[] data, int offset, int value) {
        data[offset] = (byte) value;
        data[offset + 1] = (byte) (value >>> 8);
        data[offset + 2] = (byte) (value >>> 16);
        data[offset + 3] = (byte) (value >>> 24);
    }
}

