class TIFFImageReaderGetRawImageTypeTests {
    @Test
    void returnsGrayByteTypeForEightBitBlackIsZeroTiff() throws IOException {
        TIFFImageReader reader = new TIFFImageReaderSpi().createReaderInstance(null);

        try (ImageInputStream input = javax.imageio.ImageIO.createImageInputStream(
                new ByteArrayInputStream(createGrayTiff()))) {
            reader.setInput(input);

            ImageTypeSpecifier type = reader.getRawImageType(0);

            assertNotNull(type);

            ColorModel colorModel = type.getColorModel();
            assertEquals(DataBuffer.TYPE_BYTE, colorModel.getTransferType());
            assertEquals(1, colorModel.getNumComponents());
            assertEquals(ColorSpace.TYPE_GRAY, colorModel.getColorSpace().getType());
            assertFalse(colorModel.hasAlpha());
            assertEquals(1, type.getSampleModel().getNumBands());
        }
        finally {
            reader.dispose();
        }
    }

    @Test
    void rejectsImageIndexBeyondAvailableDirectories() throws IOException {
        TIFFImageReader reader = new TIFFImageReaderSpi().createReaderInstance(null);

        try (ImageInputStream input = javax.imageio.ImageIO.createImageInputStream(
                new ByteArrayInputStream(createGrayTiff()))) {
            reader.setInput(input);

            assertThrows(IOException.class, () -> reader.getRawImageType(1));
        }
        finally {
            reader.dispose();
        }
    }

    private static byte[] createGrayTiff() {
        final int stripOffset = 110;
        ByteBuffer buffer = ByteBuffer.allocate(stripOffset + 1).order(ByteOrder.LITTLE_ENDIAN);

        buffer.put((byte) 'I');
        buffer.put((byte) 'I');
        buffer.putShort((short) 42);
        buffer.putInt(8);

        buffer.putShort((short) 8);

        putShortEntry(buffer, 256, 1);
        putShortEntry(buffer, 257, 1);
        putShortEntry(buffer, 258, 8);
        putShortEntry(buffer, 259, 1);
        putShortEntry(buffer, 262, 1);
        putLongEntry(buffer, 273, stripOffset);
        putLongEntry(buffer, 278, 1);
        putLongEntry(buffer, 279, 1);

        buffer.putInt(0);
        buffer.put((byte) 127);

        return buffer.array();
    }

    private static void putShortEntry(ByteBuffer buffer, int tag, int value) {
        buffer.putShort((short) tag);
        buffer.putShort((short) 3);
        buffer.putInt(1);
        buffer.putShort((short) value);
        buffer.putShort((short) 0);
    }

    private static void putLongEntry(ByteBuffer buffer, int tag, int value) {
        buffer.putShort((short) tag);
        buffer.putShort((short) 4);
        buffer.putInt(1);
        buffer.putInt(value);
    }
}

