class TIFFImageReaderGetRawImageTypeTests {
    @Test
    void returnsGrayWithUnassociatedAlphaWhenExtraSamplesTagIsMissing() throws IOException {
        TIFFImageReader reader = new TIFFImageReader(new TIFFImageReaderSpi());

        try (ImageInputStream input = javax.imageio.ImageIO.createImageInputStream(
                new ByteArrayInputStream(createGrayAlphaTiff()))) {
            reader.setInput(input);

