package com.twelvemonkeys.imageio.plugins.webp.lossless;

import org.junit.jupiter.api.Test;

import java.awt.image.DataBuffer;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;

class PredictorTransformApplyInverseTests {
    @Test
    void appliesTopRightPredictionUsingLeftmostPixelOnRightEdge() {
        WritableRaster pixels = createRaster(4, 3);
        Raster predictors = createRaster(4, 3);

        pixels.setPixel(0, 1, new int[]{10, 20, 30, 40});
        pixels.setPixel(3, 1, new int[]{1, 2, 3, 4});

        for (int y = 0; y < predictors.getHeight(); y++) {
            for (int x = 0; x < predictors.getWidth(); x++) {
                ((WritableRaster) predictors).setSample(x, y, 1, PredictorMode.BLACK);
            }
        }
        ((WritableRaster) predictors).setSample(3, 1, 1, PredictorMode.TR);

        PredictorTransform transform = new PredictorTransform(predictors, (byte) 0);

        assertDoesNotThrow(() -> transform.applyInverse(pixels));

        assertArrayEquals(
                new byte[]{11, 22, 33, 43},
                (byte[]) pixels.getDataElements(3, 1, null)
        );
        assertArrayEquals(
                new byte[]{0, 0, 0, (byte) 0xff},
                (byte[]) pixels.getDataElements(0, 0, null)
        );
    }

    private static WritableRaster createRaster(int width, int height) {
        return Raster.createInterleavedRaster(
                DataBuffer.TYPE_BYTE,
                width,
                height,
                width * 4,
                4,
                new int[]{0, 1, 2, 3},
                null
        );
    }
}

