package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class LoopFilterLoopFilterUVBlockTests {
    @Test
    void filtersContrastingUvEdgesInPlace() throws Exception {
        MacroBlock current = new MacroBlock(1, 1, false);
        MacroBlock left = new MacroBlock(0, 1, false);
        MacroBlock top = new MacroBlock(1, 0, false);

        setFilterLevel(current, 63);

        initialiseChroma(current, true);
        initialiseChroma(left, false);
        initialiseChroma(top, false);

        String currentUBefore = state(current, SubBlock.Plane.U);
        String currentVBefore = state(current, SubBlock.Plane.V);
        String leftUBefore = state(left, SubBlock.Plane.U);
        String topVBefore = state(top, SubBlock.Plane.V);

        LoopFilter.loopFilterUVBlock(current, left, top, 0, 1);

        assertNotEquals(currentUBefore, state(current, SubBlock.Plane.U));
        assertNotEquals(currentVBefore, state(current, SubBlock.Plane.V));
        assertNotEquals(leftUBefore, state(left, SubBlock.Plane.U));
        assertNotEquals(topVBefore, state(top, SubBlock.Plane.V));
    }

    private static void setFilterLevel(MacroBlock macroBlock, int level) throws Exception {
        Field field = MacroBlock.class.getDeclaredField("filterLevel");
        field.setAccessible(true);
        field.setInt(macroBlock, level);
    }

    private static void initialiseChroma(MacroBlock macroBlock, boolean current) throws Exception {
        for (SubBlock.Plane plane : new SubBlock.Plane[]{SubBlock.Plane.U, SubBlock.Plane.V}) {
            for (int x = 0; x < 2; x++) {
                for (int y = 0; y < 2; y++) {
                    SubBlock subBlock = macroBlock.getSubBlock(plane, x, y);
                    int value = current && (x == 0 || y == 0) ? 150 : 100;
                    fillNumericArrays(subBlock, value);
                }
            }
        }
    }

    private static void fillNumericArrays(Object object, int value) throws Exception {
        for (Field field : object.getClass().getDeclaredFields()) {
            if (!field.getType().isArray()) {
                continue;
            }

            field.setAccessible(true);
            Object array = field.get(object);
            if (array != null) {
                fillArray(array, value);
            }
        }
    }

    private static void fillArray(Object array, int value) {
        int length = Array.getLength(array);
        Class<?> componentType = array.getClass().getComponentType();

        if (componentType.isArray()) {
            for (int i = 0; i < length; i++) {
                Object nested = Array.get(array, i);
                if (nested != null) {
                    fillArray(nested, value);
                }
            }
        }
        else if (componentType == int.class
                || componentType == short.class
                || componentType == byte.class
                || componentType == long.class) {
            for (int i = 0; i < length; i++) {
                Array.set(array, i, value);
            }
        }
    }

    private static String state(MacroBlock macroBlock, SubBlock.Plane plane) throws Exception {
        StringBuilder state = new StringBuilder();

        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                SubBlock subBlock = macroBlock.getSubBlock(plane, x, y);
                state.append(x).append(':').append(y).append(';');

                for (Field field : subBlock.getClass().getDeclaredFields()) {
                    if (!field.getType().isArray()) {
                        continue;
                    }

                    field.setAccessible(true);
                    Object value = field.get(subBlock);
                    state.append(field.getName()).append('=');
                    appendArray(state, value);
                    state.append(';');
                }
            }
        }

        return state.toString();
    }

    private static void appendArray(StringBuilder state, Object array) {
        if (array == null) {
            state.append("null");
        }
        else if (array instanceof int[]) {
            state.append(Arrays.toString((int[]) array));
        }
        else if (array instanceof short[]) {
            state.append(Arrays.toString((short[]) array));
        }
        else if (array instanceof byte[]) {
            state.append(Arrays.toString((byte[]) array));
        }
        else if (array instanceof long[]) {
            state.append(Arrays.toString((long[]) array));
        }
        else if (array.getClass().getComponentType().isArray()) {
            state.append('[');
            int length = Array.getLength(array);
            for (int i = 0; i < length; i++) {
                appendArray(state, Array.get(array, i));
                state.append(',');
            }
            state.append(']');
        }
        else {
            state.append(String.valueOf(array));
        }
    }
}

