        setFilterLevel(current, 10);

        for (int row = 0; row < 2; row++) {
            for (int column = 0; column < 2; column++) {
                fill(current.getSubBlock(SubBlock.Plane.U, column, row), 80);
                fill(current.getSubBlock(SubBlock.Plane.V, column, row),
                        row == 0 ? 100 : 110);
            }
        }

        int before = current.getSubBlock(SubBlock.Plane.V, 0, 0).getDest()[0][3];

        LoopFilter.loopFilterUVBlock(current, null, null, 5, 0);

