    private static void setFilterLevel(MacroBlock macroBlock, int level)
            throws ReflectiveOperationException {
        Field field = MacroBlock.class.getDeclaredField("filterLevel");
        field.setAccessible(true);
        field.setInt(macroBlock, level);
    }

    private static void fill(SubBlock subBlock, int value)
            throws ReflectiveOperationException {
        int[][] pixels = new int[4][4];
