package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;

import javax.imageio.stream.MemoryCacheImageInputStream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class MacroBlockPredictUVTests {
    @Test
    void dcPredictionUsesIndependentUAndVNeighborAverages() throws Exception {
        VP8Frame frame = new VP8Frame(
                new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])),
                false
        );

        MacroBlock target = new MacroBlock(2, 2, false);
        MacroBlock above = new MacroBlock(2, 1, false);
        MacroBlock left = new MacroBlock(1, 2, false);

        configureNeighbors(above, 10, 100);
        configureNeighbors(left, 20, 200);

        /*
         * MacroBlock coordinates are zero-based internally. The target is at
         * (1, 1), so VP8Frame resolves its above neighbor from the previous
         * macroblock row and its left neighbor from the current row.
         */
        MacroBlock[] currentRow = new MacroBlock[3];
        MacroBlock[] previousRow = new MacroBlock[3];

        currentRow[1] = left;
        currentRow[2] = target;
        previousRow[2] = above;

        setField(frame, "currentMacroBlockRowIndex", 1);
        setField(frame, "currentMacroBlockRow", currentRow);
        setField(frame, "previousMacroBlockRow", previousRow);
        setField(target, "uvMode", Globals.DC_PRED);

        invoke(target, "predictUV", VP8Frame.class, frame);

        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                assertPrediction(getSubBlock(target, "uSubBlocks", x, y), 15);
                assertPrediction(getSubBlock(target, "vSubBlocks", x, y), 150);
            }
        }
    }

    private static void configureNeighbors(MacroBlock macroBlock, int uValue, int vValue)
            throws Exception {
        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                setField(getSubBlock(macroBlock, "uSubBlocks", x, y),
                        "recon", filled(uValue));
                setField(getSubBlock(macroBlock, "vSubBlocks", x, y),
                        "recon", filled(vValue));
            }
        }
    }

    private static SubBlock getSubBlock(MacroBlock macroBlock, String fieldName, int x, int y)
            throws Exception {
        SubBlock[][] blocks = (SubBlock[][]) getField(macroBlock, fieldName);
        return blocks[x][y];
    }

    private static void assertPrediction(SubBlock subBlock, int expected) throws Exception {
        int[][] prediction = (int[][]) getField(subBlock, "predict");
        assertNotNull(prediction);

        for (int[] row : prediction) {
            for (int value : row) {
                assertEquals(expected, value);
            }
        }
    }

    private static int[][] filled(int value) {
        int[][] result = new int[4][4];

        for (int[] row : result) {
            Arrays.fill(row, value);
        }

        return result;
    }

    private static Object getField(Object object, String name) throws Exception {
        Field field = findField(object.getClass(), name);
        field.setAccessible(true);
        return field.get(object);
    }

    private static void setField(Object object, String name, Object value) throws Exception {
        Field field = findField(object.getClass(), name);
        field.setAccessible(true);
        field.set(object, value);
    }

    private static Field findField(Class<?> type, String name) throws NoSuchFieldException {
        for (Class<?> current = type; current != null; current = current.getSuperclass()) {
            try {
                return current.getDeclaredField(name);
            }
            catch (NoSuchFieldException ignored) {
                // Continue searching inherited state.
            }
        }

        throw new NoSuchFieldException(name);
    }

    private static Object invoke(Object target, String name, Class<?> parameterType, Object argument)
            throws Exception {
        Method method = target.getClass().getDeclaredMethod(name, parameterType);
        method.setAccessible(true);
        return method.invoke(target, argument);
    }
}

