package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.assertEquals;

class MacroBlockPredictUVTests {
    @Test
    void verticalUvPredictionUsesTheCorrespondingAboveColumn() throws Exception {
        VP8Frame frame = new VP8Frame(
                new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])),
                false
        );

        MacroBlock target = new MacroBlock(1, 1, false);
        MacroBlock above = new MacroBlock(1, 0, false);
        MacroBlock left = new MacroBlock(0, 1, false);
        MacroBlock aboveLeft = new MacroBlock(0, 0, false);

        /*
         * VP8Frame.getMacroBlock uses mbCol + 1 to account for the
         * left-border entry in each row.
         */
        MacroBlock[] previousMacroBlockRow = new MacroBlock[4];
        previousMacroBlockRow[1] = aboveLeft;
        previousMacroBlockRow[2] = above;

        MacroBlock[] currentMacroBlockRow = new MacroBlock[4];
        currentMacroBlockRow[1] = left;
        currentMacroBlockRow[2] = target;

        /*
         * Provide the fallback rows as well, since getMacroBlock accesses
         * them for coordinates outside the active two-row window.
         */
        MacroBlock[] topMacroBlockRow = new MacroBlock[4];
        topMacroBlockRow[1] = aboveLeft;
        topMacroBlockRow[2] = above;

        MacroBlock[] lastNonBPredMacroBlockByColumn = new MacroBlock[4];
        lastNonBPredMacroBlockByColumn[1] = aboveLeft;
        lastNonBPredMacroBlockByColumn[2] = above;

        setField(frame, "macroBlockCols", 2);
        setField(frame, "macroBlockRows", 2);
        setField(frame, "currentMacroBlockRowIndex", target.getY());
        setField(frame, "previousMacroBlockRow", previousMacroBlockRow);
        setField(frame, "currentMacroBlockRow", currentMacroBlockRow);
        setField(frame, "topMacroBlockRow", topMacroBlockRow);
        setField(frame, "lastNonBPredMacroBlockByColumn", lastNonBPredMacroBlockByColumn);

        setField(target, "uvMode", Globals.V_PRED);

        setRecon(above.uSubBlocks[0][1], 10);
        setRecon(above.uSubBlocks[1][1], 70);
        setRecon(above.vSubBlocks[0][1], 110);
        setRecon(above.vSubBlocks[1][1], 170);

        target.predictUV(frame);

        int[][] firstUPrediction = getField(target.uSubBlocks[0][0], "predict");
        int[][] secondUPrediction = getField(target.uSubBlocks[1][0], "predict");
        int[][] firstVPrediction = getField(target.vSubBlocks[0][0], "predict");
        int[][] secondVPrediction = getField(target.vSubBlocks[1][0], "predict");

        for (int row = 0; row < 4; row++) {
            assertEquals(10, firstUPrediction[row][0]);
            assertEquals(70, secondUPrediction[row][0]);
            assertEquals(110, firstVPrediction[row][0]);
            assertEquals(170, secondVPrediction[row][0]);
        }
    }

    private static void setRecon(SubBlock subBlock, int value) throws Exception {
        int[][] recon = new int[4][4];
        for (int row = 0; row < recon.length; row++) {
            recon[row][3] = value + row;
        }
        setField(subBlock, "recon", recon);
    }

    @SuppressWarnings("unchecked")
    private static <T> T getField(Object object, String name) throws Exception {
        Field field = findField(object.getClass(), name);
        field.setAccessible(true);
        return (T) field.get(object);
    }

    private static void setField(Object object, String name, Object value) throws Exception {
        Field field = findField(object.getClass(), name);
        field.setAccessible(true);
        field.set(object, value);
    }

    private static Field findField(Class<?> type, String name) throws NoSuchFieldException {
        Class<?> current = type;
        while (current != null) {
            try {
                return current.getDeclaredField(name);
            }
            catch (NoSuchFieldException ignored) {
                current = current.getSuperclass();
            }
        }
        throw new NoSuchFieldException(name);
    }
}

