package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.assertEquals;

class MacroBlockPredictYTests {
    @Test
    void trueMotionPredictionUsesTheTopEdgeOfEachAboveSubBlock() throws Exception {
        VP8Frame frame = new VP8Frame(
                new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])),
                false
        );

        MacroBlock[][] macroBlocks = new MacroBlock[3][3];
        for (int y = 0; y < macroBlocks.length; y++) {
            for (int x = 0; x < macroBlocks[y].length; x++) {
                macroBlocks[y][x] = new MacroBlock(x, y, false);
                setRecon(macroBlocks[y][x], 0);
            }
        }

        setField(frame, "macroBlocks", macroBlocks);
        setField(frame, "macroBlockCols", 3);
        setField(frame, "macroBlockRows", 3);

        /*
         * VP8Frame resolves neighbouring macroblocks through the row buffers
         * used while decoding.  Populate those buffers so predictY can resolve
         * the target's above, left, and above-left macroblocks.
         */
        setField(frame, "currentMacroBlockRowIndex", 1);
        setField(frame, "currentMacroBlockRow", paddedRow(macroBlocks[2]));
        setField(frame, "previousMacroBlockRow", paddedRow(macroBlocks[1]));

        MacroBlock target = macroBlocks[2][2];
        target.setYMode(Globals.TM_PRED);

        MacroBlock above = macroBlocks[1][2];
        for (int x = 0; x < 4; x++) {
            setRecon(above.getYSubBlock(x, 3), 100 + x * 10);
        }
        setRecon(above.getYSubBlock(3, 0), 7);

        MacroBlock left = macroBlocks[2][1];
        for (int y = 0; y < 4; y++) {
            setRecon(left.getYSubBlock(3, y), 30 + y * 10);
        }

        setRecon(macroBlocks[1][1].getYSubBlock(3, 3), 20);

        target.predictY(frame);

        int[][] destination = getDestination(target.getYSubBlock(0, 0));
        assertEquals(110, destination[0][0]);
    }

    private static MacroBlock[] paddedRow(MacroBlock[] row) {
        MacroBlock[] padded = new MacroBlock[row.length + 1];
        System.arraycopy(row, 0, padded, 1, row.length);
        return padded;
    }

    private static void setRecon(MacroBlock macroBlock, int value) throws Exception {
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                setRecon(macroBlock.getYSubBlock(x, y), value);
            }
        }
    }

    private static void setRecon(SubBlock subBlock, int value) throws Exception {
        int[][] recon = new int[4][4];
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                recon[x][y] = value;
            }
        }
        setField(subBlock, "recon", recon);
    }

    private static int[][] getDestination(SubBlock subBlock) throws Exception {
        Field field = SubBlock.class.getDeclaredField("dest");
        field.setAccessible(true);
        return (int[][]) field.get(subBlock);
    }

    private static void setField(Object object, String name, Object value) throws Exception {
        Field field = object.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(object, value);
    }
}

