        setField(frame, "macroBlockCols", 1);
        setField(frame, "macroBlockRows", 1);
        setField(frame, "currentMacroBlockRowIndex", 0);
        setField(frame, "currentMacroBlockRow", macroBlocks[1]);
        setField(frame, "previousMacroBlockRow", null);
        setField(frame, "topMacroBlockRow", macroBlocks[0]);
    }

    private static void setRecon(SubBlock subBlock, int[][] reconstruction)
            throws ReflectiveOperationException {
        setField(subBlock, "recon", reconstruction);
    }

    private static int[][] getPredict(SubBlock subBlock)
            throws ReflectiveOperationException {
        Field field = SubBlock.class.getDeclaredField("predict");
        field.setAccessible(true);
        return (int[][]) field.get(subBlock);
    }

    private static void setField(Object target, String name, Object value)
            throws ReflectiveOperationException {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
