class SubBlockPredictTests {
    @Test
    void dcPredictionUsesTheFourTopAndFourLeftReconstructedSamples() throws Exception {
        VP8Frame frame = new VP8Frame(emptyImageStream(), false);

        MacroBlock[][] macroBlocks = new MacroBlock[3][5];
        for (int row = 0; row < macroBlocks.length; row++) {
            for (int col = 0; col < macroBlocks[row].length; col++) {
                macroBlocks[row][col] = newMacroBlock(col, row, false);
                initializeReconSamples(macroBlocks[row][col]);
            }
        }

        setField(frame, "macroBlocks", macroBlocks);
        setField(frame, "macroBlockRows", 3);
        setField(frame, "macroBlockCols", 3);

        MacroBlock currentMacroBlock = macroBlocks[1][2];
        SubBlock current = currentMacroBlock.getYSubBlock(1, 1);
        current.setMode(Globals.B_DC_PRED);

