        int[][] expected = {
                {45, 45, 45, 45},
                {45, 45, 45, 45},
                {45, 45, 45, 45},
                {45, 45, 45, 45}
        };

        assertArrayEquals(expected, current.getPredict());
    }

    private static MacroBlock newMacroBlock(int column, int row, boolean debug) throws Exception {
        for (Constructor<?> constructor : MacroBlock.class.getDeclaredConstructors()) {
            Class<?>[] parameters = constructor.getParameterTypes();
            if (parameters.length == 3
                    && parameters[0] == int.class
                    && parameters[1] == int.class
