        };
    }

    private static void setRecon(SubBlock subBlock, int[][] samples) throws Exception {
        setField(subBlock, "recon", samples);
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static ImageInputStream emptyImageStream() {
        return new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0]));
    }
